#include <bits/stdc++.h>
using namespace std;

using ll = long long;

vector<ll> smallDivisors(ll n) {
    vector<ll> divisors;
    for (ll i = 1; i <= n / i; ++i)
        if (n % i == 0)
            divisors.push_back(i);
    return divisors;
}

bool fits(const vector<ll>& divisors, ll area, ll width, ll height) {
    auto it = upper_bound(divisors.begin(), divisors.end(), height);
    if (it == divisors.begin()) return false;
    ll d = *prev(it);
    return area / d <= width;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll x, y;
    cin >> x >> y;

    ll z = x + y;
    vector<ll> dx = smallDivisors(x);
    vector<ll> dy = smallDivisors(y);

    ll ans = LLONG_MAX;

    for (ll i = 1; i <= z / i; ++i) {
        if (z % i != 0) continue;

        ll width = z / i;
        ll height = i;

        if (fits(dx, x, width, height) || fits(dy, y, width, height))
            ans = min(ans, 2 * (width + height));
    }

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct DivisorPair {
    ll a, b;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll x, y;
    cin >> x >> y;

    const ll z = x + y;
    vector<DivisorPair> a, b;

    for (ll i = 1; i <= x / i; ++i)
        if (x % i == 0)
            a.push_back({x / i, i});

    for (ll i = 1; i <= y / i; ++i)
        if (y % i == 0)
            b.push_back({y / i, i});

    size_t cnt1 = a.size(), cnt2 = b.size();
    ll ans = (ll)1e18;

    for (ll i = 1; i <= z / i; ++i) {
        if (z % i != 0) continue;

        const ll width = z / i;
        const ll height = i;

        while (cnt1 && a[cnt1 - 1].a > width) --cnt1;
        if (cnt1 && a[cnt1 - 1].b <= height)
            ans = min(ans, 2 * (width + height));

        while (cnt2 && b[cnt2 - 1].a > width) --cnt2;
        if (cnt2 && b[cnt2 - 1].b <= height)
            ans = min(ans, 2 * (width + height));
    }

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct FactorPair {
    ll a, b;
};

vector<FactorPair> getFactorPairs(ll n) {
    vector<FactorPair> factors;
    for (ll i = 1; i <= n / i; ++i) {
        if (n % i == 0) {
            factors.push_back({n / i, i});
        }
    }
    return factors;
}

bool fits(const vector<FactorPair>& factors, ll width, ll height) {
    size_t left = 0, right = factors.size();
    while (left < right) {
        size_t mid = left + (right - left) / 2;
        if (factors[mid].a <= width)
            right = mid;
        else
            left = mid + 1;
    }
    return left < factors.size() && factors[left].b <= height;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll x, y;
    cin >> x >> y;

    ll z = x + y;
    vector<FactorPair> a = getFactorPairs(x);
    vector<FactorPair> b = getFactorPairs(y);

    ll ans = LLONG_MAX;
    for (ll i = 1; i <= z / i; ++i) {
        if (z % i == 0) {
            ll width = z / i;
            ll height = i;
            if (fits(a, width, height) || fits(b, width, height)) {
                ans = min(ans, 2 * (width + height));
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

